package io.github.mekkiamiri.ratchet.order.domain;

import static org.assertj.core.api.Assertions.assertThat;

import java.math.BigDecimal;
import java.time.Instant;
import org.junit.jupiter.api.Test;

class OrderTotalCheck {

    private final Order order = new Order(new OrderId("o-1"), "ada", Instant.parse("2027-04-14T09:00:00Z"));

    @Test
    void anOrderWithoutLinesHasAZeroTotal() {
        assertThat(order.total()).isEqualByComparingTo("0");
    }

    @Test
    void totalOfASingleLineIsQuantityTimesUnitPrice() {
        order.addLine(new OrderLine("CAFE", 3, new BigDecimal("2.50")));

        assertThat(order.total()).isEqualByComparingTo("7.50");
    }

    @Test
    void totalSumsEveryLine() {
        order.addLine(new OrderLine("CAFE", 2, new BigDecimal("2.50")));
        order.addLine(new OrderLine("THE", 1, new BigDecimal("3.20")));

        assertThat(order.total()).isEqualByComparingTo("8.20");
    }

    @Test
    void totalIsExactWithoutFloatingPointDrift() {
        order.addLine(new OrderLine("A", 1, new BigDecimal("0.10")));
        order.addLine(new OrderLine("B", 1, new BigDecimal("0.20")));

        assertThat(order.total()).isEqualByComparingTo("0.30");
    }

    @Test
    void totalFollowsLinesAddedLater() {
        order.addLine(new OrderLine("CAFE", 1, new BigDecimal("1.00")));
        assertThat(order.total()).isEqualByComparingTo("1.00");

        order.addLine(new OrderLine("THE", 2, new BigDecimal("1.50")));
        assertThat(order.total()).isEqualByComparingTo("4.00");
    }

    @Test
    void totalIsUnchangedByConfirmation() {
        order.addLine(new OrderLine("CAFE", 2, new BigDecimal("2.50")));
        order.confirm();

        assertThat(order.total()).isEqualByComparingTo("5.00");
    }
}
